  (* [comment removed for export] *)
  Section Miss.
    Let POSTR := enq_refill_pre_post sp gp tp s7 s8 s9 s10 s11 F fc m lo U size TH qcache.
    Hypothesis LAh : k <> 0 -> (rw_cells bsegs m LA [C8 (wz 0)] /\ rw_cells bsegs m (LA + 16) [C8 (wz kBatchCount)])
                     /\ AHI_LO <= LA /\ LA + kBatchSize <= aceil /\ (TH + 4096 <= LA \/ LA + kBatchSize <= TH).

    Theorem enq_refill_pre :
      mem_inv bsegs m -> stk bsegs m lo (bv_unsigned sp + -2208) ->
      rw_cells bsegs m (TH + OT_TQ) [C8 (wz k); C8 (wz hdq); C8 (wz LA); C8 (wz qbytes)] ->
      rw_cells bsegs m (TH + 2128) [C4 (wz 0)] ->
      evt bsegs (fun ms' => exists jk, POSTR jk ms')
        (MS (mkR (wz 0x54624) (Z_to_bv 64 (bv_unsigned sp + -2208)) gp tp t0 t1 t2 (wz (AINST + OI_Q)) (wz (TH + OT_TQ))
                 (wz (TH + OT_TQ)) (wz (TH + OT_CACHE)) (Z_to_bv 64 (bv_unsigned sp + -2128)) (wz (U + -16)) (wz size) a5 a6 a7
                 (wz size) (Z_to_bv 64 (bv_unsigned sp + -2128)) (wz (TH + OT_CACHE)) (wz (U + -16)) (wz qcache) s7 s8 s9 s10 s11 t3 t4 t5 t6)
